function exportarCSV(nombreArchivo, columnas, filas) {
  const escapar = (v) => `"${String(v ?? "").replace(/"/g, '""')}"`;
  const encabezado = columnas.map((c) => escapar(c.titulo)).join(",");
  const lineas = filas.map((f) => columnas.map((c) => escapar(c.valor(f))).join(","));
  const csv = [encabezado, ...lineas].join("\n");
  const blob = new Blob(["﻿" + csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = nombreArchivo;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// SHA-256 en hexadecimal, usado como hash de integridad de documentos: al
// firmar, se guarda el hash del contenido en ese momento; al ver el
// documento después, se recalcula y se compara — si no coincide, alguien lo
// modificó después de firmado (Ley 527 de 1999, art. 7).
async function sha256Hex(texto) {
  try {
    const bytes = new TextEncoder().encode(texto || "");
    const digest = await crypto.subtle.digest("SHA-256", bytes);
    return Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, "0")).join("");
  } catch (e) {
    // Navegador sin Web Crypto (muy raro): sin hash, no rompe el flujo.
    return null;
  }
}

function generarReciboImagen(clienteId, cliente, pago) {
  return new Promise((resolve) => {
    const width = 720;
    const height = 920;
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d");

    ctx.fillStyle = "#FFFFFF";
    ctx.fillRect(0, 0, width, height);

    ctx.fillStyle = "#0A2342";
    ctx.fillRect(0, 0, width, 160);

    const dibujarResto = () => {
      ctx.fillStyle = "#FFFFFF";
      ctx.font = "700 27px Georgia";
      ctx.fillText(getNombreDespacho(), 165, 78);
      ctx.font = "italic 16px Georgia";
      ctx.fillStyle = "#B9CBE5";
      ctx.fillText("Recibo de pago", 165, 104);

      ctx.fillStyle = "#0A2342";
      ctx.font = "700 25px Georgia";
      ctx.fillText("RECIBO DE PAGO", 44, 218);
      ctx.strokeStyle = "#0A2342";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(44, 234);
      ctx.lineTo(width - 44, 234);
      ctx.stroke();

      let y = 272;
      const fila = (etiqueta, valor) => {
        ctx.font = "400 15px Arial";
        ctx.fillStyle = "#3B4657";
        ctx.fillText(etiqueta, 44, y);
        ctx.font = "700 16px Arial";
        ctx.fillStyle = "#0B1220";
        ctx.fillText(valor, 210, y);
        y += 34;
      };

      fila("Cliente:", cliente.nombre || "");
      fila("Fecha:", new Date(pago.fecha).toLocaleDateString("es-CO", { dateStyle: "long" }));
      fila("Medio de pago:", pago.medioPago || "");
      if (pago.concepto) fila("Concepto:", pago.concepto);

      y += 20;
      ctx.fillStyle = "#E8EEF7";
      ctx.fillRect(44, y, width - 88, 118);
      ctx.strokeStyle = "#C7D6EA";
      ctx.lineWidth = 1.5;
      ctx.strokeRect(44, y, width - 88, 118);
      ctx.fillStyle = "#6B7480";
      ctx.font = "700 13px Arial";
      ctx.fillText("VALOR PAGADO", 66, y + 34);
      ctx.fillStyle = "#0A2342";
      ctx.font = "700 42px Georgia";
      ctx.fillText(formatoCOP(pago.valor), 66, y + 88);

      ctx.fillStyle = "#8B8577";
      ctx.font = "400 12px Arial";
      ctx.fillText(`Recibo N.º ${pago.id}`, 44, height - 86);
      ctx.fillText(`Comprobante generado electrónicamente · ${getNombreDespacho()}`, 44, height - 62);

      // Se sube al bucket "recibos" (privado, aislado por despacho) en vez
      // de guardar la imagen completa dentro de la fila del cliente — así
      // cientos de recibos no inflan el límite de espacio de la base de
      // datos. Si por lo que sea la subida falla (sin internet, bucket no
      // creado todavía), se cae de vuelta al base64 de siempre para no
      // perder el recibo.
      canvas.toBlob(async (blob) => {
        try {
          if (!blob) throw new Error("No se pudo generar la imagen");
          const ruta = await subirReciboImagen(clienteId, pago.id, blob);
          resolve(ruta);
        } catch (e) {
          console.warn("No se pudo subir el recibo a Storage, se guarda como antes:", e);
          resolve(canvas.toDataURL("image/png"));
        }
      }, "image/png");
    };

    const logoImg = new Image();
    logoImg.onload = () => {
      ctx.save();
      ctx.beginPath();
      ctx.arc(90, 80, 50, 0, Math.PI * 2);
      ctx.closePath();
      ctx.clip();
      ctx.drawImage(logoImg, 40, 30, 100, 100);
      ctx.restore();
      dibujarResto();
    };
    logoImg.onerror = dibujarResto;
    logoImg.src = LOGO_SRC;
  });
}

