// Freno del lado del cliente contra intentos repetidos de inicio de sesión y
// contra el "bombardeo" de correos de recuperación de contraseña. No
// reemplaza los límites del servidor (Supabase Auth ya los tiene) — es una
// capa adicional, y por eso se guarda en localStorage: así sobrevive a
// recargar la página, que es lo primero que probaría alguien para saltársela.
const LLAVE_INTENTOS_LOGIN = "nomos_intentos_login";
const LLAVE_COOLDOWN_RECUPERACION = "nomos_cooldown_recuperacion";

function leerJSONLocal(llave, porDefecto) {
  try {
    const raw = localStorage.getItem(llave);
    return raw ? JSON.parse(raw) : porDefecto;
  } catch {
    return porDefecto;
  }
}

function guardarJSONLocal(llave, valor) {
  try {
    localStorage.setItem(llave, JSON.stringify(valor));
  } catch {
    // localStorage puede fallar (modo incógnito estricto, cuota llena) — el
    // freno simplemente no persiste entre recargas en ese caso, sin romper
    // el inicio de sesión.
  }
}

function useCuentaRegresiva(hastaCuando) {
  const [segundos, setSegundos] = useState(0);
  useEffect(() => {
    if (!hastaCuando) {
      setSegundos(0);
      return;
    }
    const tick = () => setSegundos(Math.max(0, Math.ceil((hastaCuando - Date.now()) / 1000)));
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [hastaCuando]);
  return segundos;
}

function LoginGate({ onIngresar, onCancelar, pantallaInicial }) {
  const { oscuro, alternar } = useTema();
  const [pantalla, setPantalla] = useState(pantallaInicial || "login"); // login | registro
  const [nombreDespacho, setNombreDespacho] = useState("");
  const [nombre, setNombre] = useState("");
  const [email, setEmail] = useState("");
  const [contrasena, setContrasena] = useState("");
  const [error, setError] = useState("");
  const [enviando, setEnviando] = useState(false);
  // Anti-spam del formulario de registro: "sitioWeb" es un campo trampa que
  // ningún humano llena (está oculto visualmente, no con display:none, para
  // que los rellenadores automáticos de formularios sí lo detecten y caigan
  // en la trampa); "iniciadoEn" marca cuándo se mostró el formulario — un
  // envío en menos de 1.5 segundos es casi seguro un bot, no una persona
  // llenando el formulario a mano.
  const [sitioWeb, setSitioWeb] = useState("");
  const [iniciadoEn] = useState(() => Date.now());
  const [bloqueadoHasta, setBloqueadoHasta] = useState(() => leerJSONLocal(LLAVE_INTENTOS_LOGIN, {}).bloqueadoHasta || 0);
  const segundosBloqueoLogin = useCuentaRegresiva(bloqueadoHasta);
  const [proximoEnvioRecuperacion, setProximoEnvioRecuperacion] = useState(() => leerJSONLocal(LLAVE_COOLDOWN_RECUPERACION, {}).proximoEnvio || 0);
  const segundosEsperaRecuperacion = useCuentaRegresiva(proximoEnvioRecuperacion);

  useEffect(() => {
    ensureFonts();
  }, []);

  const cambiarPantalla = (nueva) => {
    setPantalla(nueva);
    setError("");
  };

  const crearDespacho = async () => {
    if (!nombreDespacho.trim() || !nombre.trim() || !email.trim() || !contrasena.trim()) return;
    const errorContrasena = validarContrasenaCliente(contrasena);
    if (errorContrasena) {
      setError(errorContrasena);
      return;
    }
    setEnviando(true);
    setError("");
    try {
      // Se crea el usuario de Auth desde el navegador (no con service_role)
      // para que Supabase mande el correo real de confirmación. Sin ese
      // correo confirmado, signUp no deja sesión activa todavía.
      const { data: signUpData, error: signUpError } = await supabase.auth.signUp({
        email: email.trim(),
        password: contrasena,
        options: { emailRedirectTo: typeof window !== "undefined" ? window.location.origin : undefined },
      });
      if (signUpError) throw signUpError;
      if (!signUpData.user) throw new Error("No se pudo crear la cuenta.");
      // Cuando el correo ya tiene una cuenta confirmada, Supabase no lo dice
      // directamente (por seguridad, para no revelar qué correos existen),
      // pero devuelve "identities" vacío en vez de la identidad nueva —
      // así se puede distinguir sin debilitar esa protección.
      if (Array.isArray(signUpData.user.identities) && signUpData.user.identities.length === 0) {
        setError("Ya existe una cuenta con este correo. Inicia sesión, o si olvidaste tu contraseña, recupérala.");
        setEnviando(false);
        return;
      }

      const response = await fetch("/api/despachos/crear", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          nombreDespacho: nombreDespacho.trim(),
          nombre: nombre.trim(),
          email: email.trim(),
          userId: signUpData.user.id,
          sitioWeb,
          segundosLlenando: (Date.now() - iniciadoEn) / 1000,
        }),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "No se pudo crear el despacho.");

      if (signUpData.session) {
        marcarLoginRecienHecho();
        onIngresar();
      } else {
        setPantalla("registro-enviado");
      }
    } catch (e) {
      setError(e.message || "No se pudo crear el despacho. Intenta de nuevo.");
    }
    setEnviando(false);
  };

  const iniciarSesion = async () => {
    if (!email.trim() || !contrasena.trim() || segundosBloqueoLogin > 0) return;
    setEnviando(true);
    setError("");
    const { error: loginError } = await supabase.auth.signInWithPassword({ email: email.trim(), password: contrasena });
    if (loginError) {
      const anterior = leerJSONLocal(LLAVE_INTENTOS_LOGIN, { intentos: 0 });
      const intentos = (anterior.intentos || 0) + 1;
      // A partir del 5º intento fallido seguido, cada uno duplica la espera
      // (30s, 60s, 120s…) hasta un tope de 5 minutos — suficiente para
      // frenar un ataque automatizado sin castigar a alguien que
      // simplemente se equivocó de contraseña una o dos veces.
      let nuevoBloqueo = 0;
      if (intentos >= 5) {
        nuevoBloqueo = Date.now() + Math.min(30 * 2 ** (intentos - 5), 300) * 1000;
        setBloqueadoHasta(nuevoBloqueo);
      }
      guardarJSONLocal(LLAVE_INTENTOS_LOGIN, { intentos, bloqueadoHasta: nuevoBloqueo });
      setError("Correo o contraseña incorrectos.");
      setEnviando(false);
      return;
    }
    guardarJSONLocal(LLAVE_INTENTOS_LOGIN, { intentos: 0, bloqueadoHasta: 0 });
    setBloqueadoHasta(0);
    setEnviando(false);
    marcarLoginRecienHecho();
    onIngresar();
  };

  const enviarRecuperacion = async () => {
    if (!email.trim() || segundosEsperaRecuperacion > 0) return;
    setEnviando(true);
    setError("");
    const { error: recError } = await supabase.auth.resetPasswordForEmail(email.trim(), {
      redirectTo: typeof window !== "undefined" ? window.location.origin : undefined,
    });
    // El freno se aplica hayamos podido enviar el correo o no — evita que
    // alguien use este formulario para bombardear de correos de
    // recuperación la bandeja de entrada de otra persona.
    const proximo = Date.now() + 45 * 1000;
    setProximoEnvioRecuperacion(proximo);
    guardarJSONLocal(LLAVE_COOLDOWN_RECUPERACION, { proximoEnvio: proximo });
    setEnviando(false);
    if (recError) {
      setError("No pudimos enviar el correo. Verifica la dirección e intenta de nuevo.");
      return;
    }
    setPantalla("recuperacion-enviada");
  };

  return (
    <div
      className={`${oscuro ? "drx-tema-oscuro" : "drx-tema-claro"} drx-glow`}
      style={{ minHeight: "100%", background: COLORS.bg, display: "flex", alignItems: "center", justifyContent: "center", padding: 24, position: "relative", overflow: "hidden" }}
    >
      <GlobalStyle />
      <TexturaGrano />
      <div
        aria-hidden="true"
        style={{
          position: "fixed",
          top: "12%",
          left: "12%",
          width: 300,
          height: 300,
          borderRadius: "50%",
          background: `radial-gradient(circle, rgba(30,95,180,${oscuro ? 0.32 : 0.16}) 0%, rgba(30,95,180,0) 70%)`,
          animation: "drx-mesh 12s ease-in-out infinite",
          transition: "background 0.3s ease",
          pointerEvents: "none",
          zIndex: 0,
        }}
      />
      <div
        aria-hidden="true"
        style={{
          position: "fixed",
          bottom: "8%",
          right: "10%",
          width: 260,
          height: 260,
          borderRadius: "50%",
          background: `radial-gradient(circle, rgba(20,184,166,${oscuro ? 0.28 : 0.14}) 0%, rgba(20,184,166,0) 70%)`,
          animation: "drx-mesh 15s ease-in-out infinite reverse",
          transition: "background 0.3s ease",
          pointerEvents: "none",
          zIndex: 0,
        }}
      />
      <div style={{ position: "absolute", top: 20, right: 20, zIndex: 1 }}>
        <BotonTema oscuro={oscuro} onClick={alternar} />
      </div>
      <div className="drx-fade-in" style={{ maxWidth: 420, width: "100%", position: "relative", zIndex: 1 }}>
      <Card style={{ width: "100%", textAlign: "center", position: "relative", borderTop: `3px solid ${COLORS.accentBright}`, boxShadow: "0 20px 50px rgba(10,35,66,0.14)" }}>
        {onCancelar && (
          <button
            onClick={onCancelar}
            title="Volver"
            style={{ position: "absolute", top: 16, left: 16, background: "none", border: "none", cursor: "pointer", fontSize: 18, color: COLORS.muted, display: "flex", alignItems: "center", gap: 4 }}
          >
            ← <span style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5 }}>Volver</span>
          </button>
        )}
        <InsigniaPlataforma grande />
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 22, margin: "0 0 4px" }}>
          {pantalla === "registro" ? "🏛️" : pantalla === "recuperar" || pantalla === "recuperacion-enviada" ? "✉️" : pantalla === "registro-enviado" ? "📬" : "🔑"}
        </p>
        <h1 style={{ fontFamily: "Inter, sans-serif", fontSize: 22, fontWeight: 800, textTransform: "uppercase", letterSpacing: 0.5, color: COLORS.headingText, margin: "0 0 4px" }}>
          {pantalla === "registro"
            ? "Registra tu despacho"
            : pantalla === "registro-enviado"
              ? "Confirma tu correo"
              : pantalla === "recuperar" || pantalla === "recuperacion-enviada"
                ? "Recuperar contraseña"
                : "Panel de gestión legal"}
        </h1>

        {pantalla === "registro" && (
          <div style={{ textAlign: "left" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, margin: "8px 0 16px" }}>
              Crea la cuenta de tu despacho — quedas como su Administrador y desde ahí creas a los demás usuarios y les das permisos. Tus datos quedan
              completamente separados de los de cualquier otro despacho.
            </p>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {/* Campo trampa para bots: invisible para personas, pero un
                  rellenador automático de formularios sí lo encuentra y lo
                  llena. Si llega lleno, el servidor rechaza el registro. */}
              <div style={{ position: "absolute", left: "-9999px", width: 1, height: 1, overflow: "hidden" }} aria-hidden="true">
                <label htmlFor="sitio-web-empresa">Sitio web</label>
                <input id="sitio-web-empresa" type="text" tabIndex={-1} autoComplete="off" value={sitioWeb} onChange={(e) => setSitioWeb(e.target.value)} />
              </div>
              <Field label="Nombre del despacho">
                <input
                  className="drx-input"
                  style={inputStyle}
                  value={nombreDespacho}
                  onChange={(e) => setNombreDespacho(e.target.value)}
                  placeholder="Ej: García & Asociados"
                  autoFocus
                />
              </Field>
              <Field label="Tu nombre">
                <input className="drx-input" style={inputStyle} value={nombre} onChange={(e) => setNombre(e.target.value)} />
              </Field>
              <Field label="Correo">
                <input
                  type="email"
                  className="drx-input"
                  style={inputStyle}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Ej: felipe@cortesramirezabogados.com"
                />
              </Field>
              <Field label="Contraseña">
                <CampoContrasena valor={contrasena} onChange={setContrasena} />
                <MedidorFuerzaContrasena valor={contrasena} />
                <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, margin: "4px 0 0" }}>
                  Mínimo 10 caracteres, combinando letras y números.
                </p>
              </Field>
            </div>
            {error && <p style={{ color: "#B42318", fontSize: 12.5, marginTop: 10, fontFamily: "Inter, sans-serif" }}>{error}</p>}
            <button
              className="drx-btn-primary drx-cta-shine"
              style={{ ...buttonPrimary, width: "100%", marginTop: 16 }}
              onClick={crearDespacho}
              disabled={enviando || !nombreDespacho.trim() || !nombre.trim() || !email.trim() || !contrasena.trim()}
            >
              {enviando ? "Creando…" : "Crear mi despacho"}
            </button>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, marginTop: 14, textAlign: "center" }}>
              ¿Ya tienes cuenta?{" "}
              <button
                onClick={() => cambiarPantalla("login")}
                style={{ background: "none", border: "none", color: COLORS.accentBright, cursor: "pointer", textDecoration: "underline", fontFamily: "Inter, sans-serif", fontSize: 11 }}
              >
                Inicia sesión
              </button>
            </p>
          </div>
        )}

        {pantalla === "registro-enviado" && (
          <div style={{ textAlign: "left" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, margin: "8px 0 16px" }}>
              Te enviamos un correo a <strong>{email}</strong> para confirmar tu cuenta. Ábrelo y confirma; después vuelve aquí e inicia sesión con tu
              correo y contraseña.
            </p>
            <button className="drx-btn-ghost" style={{ ...buttonGhost, width: "100%" }} onClick={() => cambiarPantalla("login")}>
              Ya confirmé, iniciar sesión
            </button>
          </div>
        )}

        {pantalla === "login" && (
          <div style={{ textAlign: "left" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, textAlign: "center", margin: "8px 0 18px" }}>Inicia sesión</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <Field label="Correo">
                <input
                  type="email"
                  className="drx-input"
                  style={inputStyle}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && iniciarSesion()}
                  autoFocus
                />
              </Field>
              <Field label="Contraseña">
                <CampoContrasena valor={contrasena} onChange={setContrasena} onEnter={iniciarSesion} autoFocus={!!email} />
              </Field>
            </div>
            {error && <p style={{ color: "#B42318", fontSize: 12.5, marginTop: 10, fontFamily: "Inter, sans-serif" }}>{error}</p>}
            {segundosBloqueoLogin > 0 && (
              <p style={{ color: "#B45309", fontSize: 12, marginTop: 10, fontFamily: "Inter, sans-serif" }}>
                Demasiados intentos fallidos. Espera {segundosBloqueoLogin}s antes de volver a intentar.
              </p>
            )}
            <button
              className="drx-btn-primary drx-cta-shine"
              style={{ ...buttonPrimary, width: "100%", marginTop: 16 }}
              onClick={iniciarSesion}
              disabled={enviando || !email.trim() || !contrasena.trim() || segundosBloqueoLogin > 0}
            >
              {segundosBloqueoLogin > 0 ? `Espera ${segundosBloqueoLogin}s` : enviando ? "Ingresando…" : "Ingresar"}
            </button>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, marginTop: 14, textAlign: "center" }}>
              <button
                onClick={() => cambiarPantalla("recuperar")}
                style={{ background: "none", border: "none", color: COLORS.accentBright, cursor: "pointer", textDecoration: "underline", fontFamily: "Inter, sans-serif", fontSize: 11 }}
              >
                ¿Olvidaste tu contraseña?
              </button>
              <br />
              ¿No tienes acceso? Pídele a tu administrador que te cree un usuario desde "Usuarios y permisos".
              <br />
              ¿Primera vez aquí?{" "}
              <button
                onClick={() => cambiarPantalla("registro")}
                style={{ background: "none", border: "none", color: COLORS.accentBright, cursor: "pointer", textDecoration: "underline", fontFamily: "Inter, sans-serif", fontSize: 11 }}
              >
                Crea tu despacho
              </button>
            </p>
          </div>
        )}

        {pantalla === "recuperar" && (
          <div style={{ textAlign: "left" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, margin: "8px 0 16px" }}>
              Escribe tu correo y te enviamos un enlace para poner una contraseña nueva.
            </p>
            <Field label="Correo">
              <input
                type="email"
                className="drx-input"
                style={inputStyle}
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && enviarRecuperacion()}
                autoFocus
              />
            </Field>
            {error && <p style={{ color: "#B42318", fontSize: 12.5, marginTop: 10, fontFamily: "Inter, sans-serif" }}>{error}</p>}
            <button
              className="drx-btn-primary"
              style={{ ...buttonPrimary, width: "100%", marginTop: 16 }}
              onClick={enviarRecuperacion}
              disabled={enviando || !email.trim() || segundosEsperaRecuperacion > 0}
            >
              {segundosEsperaRecuperacion > 0 ? `Espera ${segundosEsperaRecuperacion}s` : enviando ? "Enviando…" : "Enviar enlace de recuperación"}
            </button>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, marginTop: 14, textAlign: "center" }}>
              <button
                onClick={() => cambiarPantalla("login")}
                style={{ background: "none", border: "none", color: COLORS.accentBright, cursor: "pointer", textDecoration: "underline", fontFamily: "Inter, sans-serif", fontSize: 11 }}
              >
                Volver a iniciar sesión
              </button>
            </p>
          </div>
        )}

        {pantalla === "recuperacion-enviada" && (
          <div style={{ textAlign: "left" }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, color: COLORS.muted, margin: "8px 0 16px" }}>
              Listo — si ese correo tiene una cuenta, te llegó un enlace para poner una contraseña nueva. Ábrelo desde el mismo dispositivo y sigue las
              instrucciones.
            </p>
            <button
              className="drx-btn-ghost"
              style={{ ...buttonGhost, width: "100%" }}
              onClick={() => cambiarPantalla("login")}
            >
              Volver a iniciar sesión
            </button>
          </div>
        )}

        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 10.5, color: COLORS.muted, marginTop: 20, lineHeight: 1.5 }}>
          Inicio de sesión real con Supabase Auth: tu contraseña nunca se guarda en texto plano, viaja cifrada y la
          verifica el servidor.
        </p>
      </Card>
      </div>
    </div>
  );
}

function PlataformaTab() {
  const [despachos, setDespachos] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState("");
  const [cambiando, setCambiando] = useState(null);

  const cargar = useCallback(async () => {
    setCargando(true);
    setError("");
    try {
      const { data: sesionData } = await supabase.auth.getSession();
      const token = sesionData?.session?.access_token;
      const response = await fetch("/api/plataforma/despachos", { headers: { Authorization: `Bearer ${token}` } });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "No se pudo cargar la lista de despachos.");
      setDespachos(data.despachos || []);
    } catch (e) {
      setError(e.message);
    }
    setCargando(false);
  }, []);

  useEffect(() => {
    cargar();
  }, [cargar]);

  const alternarActivo = async (despacho) => {
    setCambiando(despacho.id);
    try {
      const { data: sesionData } = await supabase.auth.getSession();
      const token = sesionData?.session?.access_token;
      const response = await fetch("/api/plataforma/despachos", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ despachoId: despacho.id, activo: !despacho.activo }),
      });
      if (!response.ok) throw new Error("No se pudo actualizar.");
      setDespachos((prev) => prev.map((d) => (d.id === despacho.id ? { ...d, activo: !d.activo } : d)));
    } catch (e) {
      setError(e.message);
    }
    setCambiando(null);
  };

  const eliminarDespacho = async (despacho) => {
    if (!window.confirm(`¿Eliminar por completo "${despacho.nombre}"? Esto borra su registro y la cuenta de quien se registró. No se puede deshacer.`)) {
      return;
    }
    setCambiando(despacho.id);
    try {
      const { data: sesionData } = await supabase.auth.getSession();
      const token = sesionData?.session?.access_token;
      const response = await fetch("/api/plataforma/despachos", {
        method: "DELETE",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ despachoId: despacho.id }),
      });
      if (!response.ok) throw new Error("No se pudo eliminar.");
      setDespachos((prev) => prev.filter((d) => d.id !== despacho.id));
    } catch (e) {
      setError(e.message);
    }
    setCambiando(null);
  };

  const pendientes = despachos.filter((d) => !d.activo);
  const activos = despachos.filter((d) => d.activo);
  const HACE_7_DIAS = Date.now() - 7 * 24 * 60 * 60 * 1000;
  const activosUsandoEstaSemana = activos.filter((d) => d.ultimaActividad && new Date(d.ultimaActividad).getTime() >= HACE_7_DIAS).length;

  const textoUltimaActividad = (fecha) => {
    if (!fecha) return "sin inicios de sesión registrados todavía";
    const dias = Math.floor((Date.now() - new Date(fecha).getTime()) / (24 * 60 * 60 * 1000));
    if (dias <= 0) return "activo hoy";
    if (dias === 1) return "activo ayer";
    return `última actividad hace ${dias} días`;
  };

  return (
    <div>
      <EncabezadoSeccion titulo="Plataforma" color="#DC2626" />

      {!cargando && activos.length > 0 && (
        <Card style={{ marginBottom: 18, borderLeft: "4px solid #2F80ED" }}>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, fontWeight: 700, color: COLORS.muted, textTransform: "uppercase", letterSpacing: 0.5, margin: 0 }}>
            Uso real, no solo pago
          </p>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 22, fontWeight: 800, color: COLORS.ink, margin: "4px 0 0" }}>
            {activosUsandoEstaSemana} de {activos.length} despachos activos entraron esta semana
          </p>
        </Card>
      )}
      <div
        style={{
          background: "#FEF3E2",
          border: "1px solid #FCE3B8",
          borderRadius: 10,
          padding: "12px 16px",
          marginBottom: 18,
          fontFamily: "Inter, sans-serif",
          fontSize: 12.5,
          color: "#92400E",
        }}
      >
        Solo tú ves esta pestaña. Aquí activas el acceso de un despacho nuevo después de coordinar el pago por WhatsApp,
        o desactivas uno que dejó de pagar.
      </div>

      {error && <p style={{ color: "#B42318", fontSize: 13, marginBottom: 14, fontFamily: "Inter, sans-serif" }}>{error}</p>}
      {cargando && <Spinner />}

      {!cargando && (
        <>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 700, color: "#B45309", marginBottom: 10 }}>
            Pendientes de activar ({pendientes.length})
          </p>
          <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 24 }}>
            {pendientes.length === 0 && <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.muted }}>Ninguno por ahora.</p>}
            {pendientes.map((d) => (
              <Card key={d.id} style={{ borderLeft: "4px solid #F5A524" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10 }}>
                  <div>
                    <p style={{ fontFamily: "Inter, sans-serif", fontSize: 14, fontWeight: 700, color: COLORS.ink, margin: 0 }}>{d.nombre}</p>
                    <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, color: COLORS.muted, margin: "2px 0 0" }}>
                      {d.adminEmail || "sin administrador"} · registrado {new Date(d.creado_en).toLocaleDateString("es-CO", { dateStyle: "medium" })}
                    </p>
                  </div>
                  <div style={{ display: "flex", gap: 8 }}>
                    <button
                      className="drx-btn-ghost"
                      style={{ ...buttonGhost, color: "#B42318", borderColor: "#F3C6C0" }}
                      onClick={() => eliminarDespacho(d)}
                      disabled={cambiando === d.id}
                    >
                      Eliminar
                    </button>
                    <button
                      className="drx-btn-primary"
                      style={{ ...buttonPrimary, background: "#10B981" }}
                      onClick={() => alternarActivo(d)}
                      disabled={cambiando === d.id}
                    >
                      {cambiando === d.id ? "…" : "✓ Activar acceso"}
                    </button>
                  </div>
                </div>
              </Card>
            ))}
          </div>

          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 700, color: "#166534", marginBottom: 10 }}>
            Activos ({activos.length})
          </p>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {activos.length === 0 && <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.muted }}>Ninguno todavía.</p>}
            {activos.map((d) => (
              <Card key={d.id} style={{ borderLeft: "4px solid #10B981" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10 }}>
                  <div>
                    <p style={{ fontFamily: "Inter, sans-serif", fontSize: 14, fontWeight: 700, color: COLORS.ink, margin: 0 }}>{d.nombre}</p>
                    <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, color: COLORS.muted, margin: "2px 0 0" }}>
                      {d.adminEmail || "sin administrador"} · registrado {new Date(d.creado_en).toLocaleDateString("es-CO", { dateStyle: "medium" })}
                    </p>
                    <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, fontWeight: 600, color: d.ultimaActividad && new Date(d.ultimaActividad).getTime() >= HACE_7_DIAS ? "#166534" : "#B45309", margin: "2px 0 0" }}>
                      {textoUltimaActividad(d.ultimaActividad)}
                    </p>
                  </div>
                  <button className="drx-btn-ghost" style={buttonGhost} onClick={() => alternarActivo(d)} disabled={cambiando === d.id}>
                    {cambiando === d.id ? "…" : "Desactivar"}
                  </button>
                </div>
              </Card>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// Los administradores ya pueden leer toda la auditoría de su despacho (ver
// política RLS "administradores leen auditoria del mismo despacho"), así que
// esto no necesita ningún permiso nuevo — solo faltaba mostrarlo.
function UltimaSesionUsuario({ usuarioId }) {
  const [fecha, setFecha] = useState(undefined);

  useEffect(() => {
    let cancelado = false;
    (async () => {
      const { data } = await supabase
        .from("auditoria")
        .select("creado_en")
        .eq("usuario_id", usuarioId)
        .eq("accion", "inicio_sesion")
        .order("creado_en", { ascending: false })
        .limit(1);
      if (!cancelado) setFecha(data?.[0]?.creado_en || null);
    })();
    return () => {
      cancelado = true;
    };
  }, [usuarioId]);

  if (fecha === undefined) return "Cargando última sesión…";
  if (!fecha) return "Sin inicios de sesión registrados todavía";
  return `Última sesión: ${new Date(fecha).toLocaleString("es-CO", { dateStyle: "medium", timeStyle: "short" })}`;
}

function UsuariosPermisosTab({ usuarioActual, onDespachoRenombrado }) {
  const usuarioActualId = usuarioActual.id;
  const { usuarios, crear: crearUsuario, actualizar, eliminar: eliminarUsuario } = useUsuariosDespacho();
  const [mostrarForm, setMostrarForm] = useState(false);
  const [nombre, setNombre] = useState("");
  const [email, setEmail] = useState("");
  const [contrasena, setContrasena] = useState("");
  const [rol, setRol] = useState("Asistente");
  const [error, setError] = useState("");
  const [creando, setCreando] = useState(false);
  const [eliminandoId, setEliminandoId] = useState(null);
  const [enviandoResetId, setEnviandoResetId] = useState(null);
  const [resetEnviadoId, setResetEnviadoId] = useState(null);

  const enviarResetContrasena = async (u) => {
    setEnviandoResetId(u.id);
    setError("");
    try {
      const { error: resetError } = await supabase.auth.resetPasswordForEmail(u.email, {
        redirectTo: typeof window !== "undefined" ? window.location.origin : undefined,
      });
      if (resetError) throw resetError;
      setResetEnviadoId(u.id);
      setTimeout(() => setResetEnviadoId(null), 4000);
    } catch (e) {
      setError("No se pudo enviar el correo de restablecimiento.");
    }
    setEnviandoResetId(null);
  };

  const eliminarUsuarioClick = async (u) => {
    if (!window.confirm(`¿Eliminar el acceso de ${u.nombre}? Ya no podrá iniciar sesión. No se puede deshacer.`)) return;
    setEliminandoId(u.id);
    setError("");
    try {
      await eliminarUsuario(u.id);
      registrarAuditoria(usuarioActual, "eliminar_usuario", "usuario", u.id, { nombre: u.nombre, rol: u.rol });
    } catch (e) {
      setError(e.message || "No se pudo eliminar el usuario.");
    }
    setEliminandoId(null);
  };
  const [nombreDespachoEdit, setNombreDespachoEdit] = useState(getNombreDespacho());
  const [editandoDespacho, setEditandoDespacho] = useState(false);
  const [guardandoDespacho, setGuardandoDespacho] = useState(false);

  const guardarNombreDespacho = async () => {
    if (!nombreDespachoEdit.trim()) return;
    setGuardandoDespacho(true);
    const { error: renombrarError } = await supabase.from("despachos").update({ nombre: nombreDespachoEdit.trim() }).eq("id", usuarioActual.despacho_id);
    setGuardandoDespacho(false);
    if (!renombrarError) {
      setDespachoActual(usuarioActual.despacho_id, nombreDespachoEdit.trim());
      onDespachoRenombrado?.(nombreDespachoEdit.trim());
      setEditandoDespacho(false);
    }
  };

  const crear = async () => {
    if (!nombre.trim() || !email.trim() || !contrasena.trim()) return;
    setCreando(true);
    setError("");
    try {
      const nuevoUsuario = await crearUsuario({ nombre: nombre.trim(), email: email.trim(), contrasena, rol });
      registrarAuditoria(usuarioActual, "crear_usuario", "usuario", nuevoUsuario?.id, { nombre: nombre.trim(), rol });
      setNombre("");
      setEmail("");
      setContrasena("");
      setRol("Asistente");
      setMostrarForm(false);
    } catch (e) {
      setError(e.message || "No se pudo crear el usuario.");
    }
    setCreando(false);
  };

  const cambiarPermiso = (u, seccionId, valor) => {
    const permisos = { ...(u.permisos || permisosPorDefecto(u.rol)), [seccionId]: valor };
    actualizar(u.id, { permisos });
    registrarAuditoria(usuarioActual, "cambiar_permiso", "usuario", u.id, { seccion: seccionId, valor, usuario: u.nombre });
  };

  const cambiarNotificacion = (u, categoriaId, valor) => {
    const notificaciones = { ...(u.notificaciones || notificacionesPorDefecto()), [categoriaId]: valor };
    actualizar(u.id, { notificaciones });
  };

  const [respaldando, setRespaldando] = useState(false);
  const [pidiendoContrasenaRespaldo, setPidiendoContrasenaRespaldo] = useState(false);
  const [contrasenaRespaldo, setContrasenaRespaldo] = useState("");
  const [errorRespaldo, setErrorRespaldo] = useState("");
  const LLAVE_COOLDOWN_RESPALDO = "nomos_cooldown_respaldo";
  const [proximoRespaldoDisponible, setProximoRespaldoDisponible] = useState(() => leerJSONLocal(LLAVE_COOLDOWN_RESPALDO, {})[usuarioActual.id] || 0);
  const segundosEsperaRespaldo = useCuentaRegresiva(proximoRespaldoDisponible);

  // Descargar TODA la información del despacho de un clic es justo lo que
  // buscaría alguien que robó una sesión activa (un computador desatendido,
  // una cookie robada) — pedir la contraseña otra vez aquí, aparte de la del
  // login, frena ese ataque puntual aunque ya esté "adentro". El enfriamiento
  // evita además que se use para sacar el respaldo una y otra vez seguido.
  const confirmarRespaldo = async () => {
    if (!contrasenaRespaldo.trim() || segundosEsperaRespaldo > 0) return;
    setErrorRespaldo("");
    const { error: reauthError } = await supabase.auth.signInWithPassword({ email: usuarioActual.email, password: contrasenaRespaldo });
    if (reauthError) {
      setErrorRespaldo("Contraseña incorrecta.");
      return;
    }
    setContrasenaRespaldo("");
    setPidiendoContrasenaRespaldo(false);
    const proximo = Date.now() + 5 * 60 * 1000;
    const mapa = leerJSONLocal(LLAVE_COOLDOWN_RESPALDO, {});
    mapa[usuarioActual.id] = proximo;
    guardarJSONLocal(LLAVE_COOLDOWN_RESPALDO, mapa);
    setProximoRespaldoDisponible(proximo);
    await descargarRespaldo();
  };

  const descargarRespaldo = async () => {
    setRespaldando(true);
    try {
      const despachoId = usuarioActual.despacho_id;
      const tablas = ["clientes", "documentos", "casos", "chats", "app_settings"];
      const respaldo = { despacho: getNombreDespacho(), generadoEn: new Date().toISOString() };
      for (const tabla of tablas) {
        const { data, error } = await supabase.from(tabla).select("*").eq("despacho_id", despachoId);
        if (error) throw error;
        respaldo[tabla] = data || [];
      }
      const contenido = JSON.stringify(respaldo, null, 2);
      const blob = new Blob([contenido], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `respaldo-${getNombreDespacho().toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${new Date().toISOString().slice(0, 10)}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      registrarAuditoria(usuarioActual, "descargar_respaldo", "despacho", despachoId, {});
    } catch (e) {
      window.alert("No se pudo generar el respaldo. Intenta de nuevo en un momento.");
    }
    setRespaldando(false);
  };

  return (
    <div>
      <EncabezadoSeccion titulo="Usuarios y permisos" color="#6B7480" />
      <div
        style={{
          background: COLORS.accentSoft,
          border: "1px solid #C7D6EA",
          borderRadius: 10,
          padding: "12px 16px",
          marginBottom: 18,
          fontFamily: "Inter, sans-serif",
          fontSize: 12.5,
          color: COLORS.navy,
        }}
      >
        Solo tú, como Administrador, puedes crear usuarios y decidir qué puede ver cada uno.
      </div>

      <Card style={{ marginBottom: 20 }}>
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 600, color: COLORS.headingText, marginBottom: 4 }}>Nombre del despacho</p>
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, marginBottom: 10 }}>
          Aparece en el menú, los PDFs, los recibos y los mensajes de WhatsApp que manda la app.
        </p>
        {editandoDespacho ? (
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            <input
              className="drx-input"
              style={{ ...inputStyle, flex: 1, minWidth: 200 }}
              value={nombreDespachoEdit}
              onChange={(e) => setNombreDespachoEdit(e.target.value)}
            />
            <button className="drx-btn-primary" style={buttonPrimary} onClick={guardarNombreDespacho} disabled={guardandoDespacho || !nombreDespachoEdit.trim()}>
              {guardandoDespacho ? "Guardando…" : "Guardar"}
            </button>
            <button
              className="drx-btn-ghost"
              style={buttonGhost}
              onClick={() => {
                setNombreDespachoEdit(getNombreDespacho());
                setEditandoDespacho(false);
              }}
            >
              Cancelar
            </button>
          </div>
        ) : (
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10 }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 15, fontWeight: 700, color: COLORS.ink, margin: 0 }}>{getNombreDespacho()}</p>
            <button className="drx-btn-ghost" style={buttonGhost} onClick={() => setEditandoDespacho(true)}>
              Editar
            </button>
          </div>
        )}
      </Card>

      <Card style={{ marginBottom: 20, borderLeft: "4px solid #10B981" }}>
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 600, color: COLORS.headingText, marginBottom: 4 }}>🛡️ Respaldo de tus datos</p>
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, marginBottom: 12 }}>
          Descarga ahora mismo un archivo con TODA la información de tu despacho (clientes, documentos, casos y contenido) tal
          como está en este momento. Guárdalo en tu computador o en la nube (Google Drive, etc.). Recomendado: descárgalo
          cada semana o antes de cualquier cambio grande.
        </p>
        {!pidiendoContrasenaRespaldo ? (
          <button
            className="drx-btn-primary"
            style={{ ...buttonPrimary, background: "#10B981" }}
            onClick={() => setPidiendoContrasenaRespaldo(true)}
            disabled={respaldando || segundosEsperaRespaldo > 0}
          >
            {segundosEsperaRespaldo > 0 ? `Vuelve a intentar en ${segundosEsperaRespaldo}s` : "⬇️ Descargar respaldo completo"}
          </button>
        ) : (
          <div style={{ maxWidth: 320 }}>
            <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.inkSoft, marginBottom: 8 }}>
              Por seguridad, escribe tu contraseña otra vez para confirmar la descarga.
            </p>
            <CampoContrasena valor={contrasenaRespaldo} onChange={setContrasenaRespaldo} onEnter={confirmarRespaldo} autoFocus />
            {errorRespaldo && <p style={{ color: "#B42318", fontSize: 12, marginTop: 6, fontFamily: "Inter, sans-serif" }}>{errorRespaldo}</p>}
            <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
              <button
                className="drx-btn-ghost"
                style={buttonGhost}
                onClick={() => {
                  setPidiendoContrasenaRespaldo(false);
                  setContrasenaRespaldo("");
                  setErrorRespaldo("");
                }}
              >
                Cancelar
              </button>
              <button className="drx-btn-primary" style={{ ...buttonPrimary, background: "#10B981" }} onClick={confirmarRespaldo} disabled={respaldando || !contrasenaRespaldo.trim()}>
                {respaldando ? "Generando respaldo…" : "Confirmar y descargar"}
              </button>
            </div>
          </div>
        )}
      </Card>

      <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 16 }}>
        <button className="drx-btn-primary" style={buttonPrimary} onClick={() => setMostrarForm((s) => !s)}>
          {mostrarForm ? "Cancelar" : "+ Nuevo usuario"}
        </button>
      </div>

      {mostrarForm && (
        <Card style={{ marginBottom: 16 }}>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            <Field label="Nombre">
              <input className="drx-input" style={inputStyle} value={nombre} onChange={(e) => setNombre(e.target.value)} />
            </Field>
            <Field label="Correo">
              <input type="email" className="drx-input" style={inputStyle} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Ej: novia@correo.com" />
            </Field>
            <Field label="Contraseña">
              <input type="password" className="drx-input" style={inputStyle} value={contrasena} onChange={(e) => setContrasena(e.target.value)} />
              <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, margin: "4px 0 0" }}>Mínimo 10 caracteres, combinando letras y números.</p>
            </Field>
            <Field label="Rol">
              <select className="drx-input" style={inputStyle} value={rol} onChange={(e) => setRol(e.target.value)}>
                <option>Administrador</option>
                <option>Abogado</option>
                <option>Asistente</option>
              </select>
            </Field>
          </div>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, color: COLORS.muted, marginTop: 10 }}>
            Los permisos se asignan según el rol y los puedes ajustar después en la lista de abajo.
          </p>
          {error && <p style={{ color: "#B42318", fontSize: 12.5, marginTop: 10, fontFamily: "Inter, sans-serif" }}>{error}</p>}
          <button
            className="drx-btn-primary"
            style={{ ...buttonPrimary, marginTop: 12 }}
            onClick={crear}
            disabled={creando || !nombre.trim() || !email.trim() || !contrasena.trim()}
          >
            {creando ? "Creando…" : "Crear usuario"}
          </button>
        </Card>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        {usuarios.map((u) => {
          const permisos = u.permisos || permisosPorDefecto(u.rol);
          return (
            <Card key={u.id}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12, flexWrap: "wrap", gap: 8 }}>
                <div>
                  <p style={{ fontFamily: "Inter, sans-serif", fontSize: 15, fontWeight: 700, color: COLORS.ink, margin: 0 }}>
                    {u.nombre} {u.id === usuarioActualId && <span style={{ color: COLORS.muted, fontWeight: 400, fontSize: 12 }}>(tú)</span>}
                  </p>
                  <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, margin: "2px 0 0" }}>
                    {u.email} · {u.rol}
                  </p>
                  <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, margin: "2px 0 0" }}>
                    <UltimaSesionUsuario usuarioId={u.id} />
                  </p>
                </div>
                <div style={{ display: "flex", gap: 8 }}>
                  <button
                    className="drx-btn-ghost"
                    style={{ ...buttonGhost, fontSize: 12, padding: "6px 12px" }}
                    onClick={() => enviarResetContrasena(u)}
                    disabled={enviandoResetId === u.id}
                  >
                    {resetEnviadoId === u.id ? "✓ Correo enviado" : enviandoResetId === u.id ? "Enviando…" : "Restablecer contraseña"}
                  </button>
                  {u.id !== usuarioActualId && (
                    <button
                      className="drx-btn-ghost"
                      style={{ ...buttonGhost, color: "#B42318", borderColor: "#F3C6C0", fontSize: 12, padding: "6px 12px" }}
                      onClick={() => eliminarUsuarioClick(u)}
                      disabled={eliminandoId === u.id}
                    >
                      {eliminandoId === u.id ? "Eliminando…" : "Eliminar acceso"}
                    </button>
                  )}
                </div>
              </div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 12 }}>
                {SECCIONES_PERMISOS.map((s) => (
                  <label key={s.id} style={{ display: "flex", alignItems: "center", gap: 6, fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.inkSoft, cursor: "pointer" }}>
                    <input type="checkbox" checked={permisos[s.id] !== false} onChange={(e) => cambiarPermiso(u, s.id, e.target.checked)} disabled={u.rol === "Administrador"} />
                    {s.nombre}
                  </label>
                ))}
              </div>
              {u.rol === "Administrador" && (
                <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, marginTop: 8, fontStyle: "italic" }}>
                  Los administradores siempre ven todas las secciones.
                </p>
              )}

              <div style={{ borderTop: `1px solid ${COLORS.border}`, marginTop: 12, paddingTop: 10 }}>
                <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11.5, fontWeight: 600, color: COLORS.muted, marginBottom: 8 }}>
                  🔔 Qué notificaciones recibe (campana)
                </p>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 12 }}>
                  {NOTIF_CATEGORIAS.map((n) => {
                    const notifs = u.notificaciones || notificacionesPorDefecto();
                    return (
                      <label key={n.id} style={{ display: "flex", alignItems: "center", gap: 6, fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.inkSoft, cursor: "pointer" }}>
                        <input type="checkbox" checked={notifs[n.id] !== false} onChange={(e) => cambiarNotificacion(u, n.id, e.target.checked)} />
                        {n.nombre}
                      </label>
                    );
                  })}
                </div>
              </div>
            </Card>
          );
        })}
      </div>

      <PapeleraPanel />
      <PanelAuditoria />
    </div>
  );
}

const TIPOS_PAPELERA = [
  { tipo: "clientes", etiqueta: "Clientes", campo: "nombre" },
  { tipo: "documentos", etiqueta: "Documentos", campo: "titulo" },
];

function PapeleraPanel() {
  const [abierto, setAbierto] = useState(false);
  const [cargado, setCargado] = useState(false);
  const [items, setItems] = useState({ clientes: [], documentos: [] });

  const cargar = useCallback(async () => {
    const [clientes, documentos] = await Promise.all([obtenerPapelera("clientes"), obtenerPapelera("documentos")]);
    setItems({ clientes, documentos });
    setCargado(true);
  }, []);

  useEffect(() => {
    if (abierto && !cargado) cargar();
  }, [abierto, cargado, cargar]);

  const restaurar = async (tipo, id) => {
    await restaurarDePapelera(tipo, id);
    cargar();
  };

  const borrarDefinitivo = async (tipo, id) => {
    if (!window.confirm("Esto borra el registro para siempre, sin poder recuperarlo. ¿Seguro?")) return;
    await eliminarDefinitivo(tipo, id);
    cargar();
  };

  const totalItems = items.clientes.length + items.documentos.length;

  return (
    <Card style={{ marginTop: 20 }}>
      <button
        onClick={() => setAbierto((a) => !a)}
        style={{ background: "none", border: "none", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center", width: "100%", padding: 0 }}
      >
        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 15, fontWeight: 700, color: COLORS.ink, margin: 0 }}>
          🗑️ Papelera {cargado ? `(${totalItems})` : ""}
        </p>
        <span style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: COLORS.muted }}>{abierto ? "Ocultar ▲" : "Ver ▼"}</span>
      </button>

      {abierto && (
        <div style={{ marginTop: 14 }}>
          <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, marginBottom: 14 }}>
            Lo que se elimina desde Clientes o Firmar documentos queda aquí, no se borra de una. Puedes recuperarlo o borrarlo para siempre.
          </p>
          {TIPOS_PAPELERA.map(({ tipo, etiqueta, campo }) => (
            <div key={tipo} style={{ marginBottom: 16 }}>
              <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, fontWeight: 700, color: COLORS.headingText, marginBottom: 8 }}>{etiqueta}</p>
              {items[tipo].length === 0 && cargado && (
                <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: COLORS.muted, margin: 0 }}>Vacía.</p>
              )}
              <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                {items[tipo].map((r) => {
                  const dias = Math.floor((Date.now() - new Date(r.eliminado_en).getTime()) / 86400000);
                  return (
                    <div
                      key={r.id}
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        flexWrap: "wrap",
                        gap: 8,
                        background: COLORS.accentSoft,
                        border: `1px solid ${COLORS.border}`,
                        borderRadius: 8,
                        padding: "8px 12px",
                      }}
                    >
                      <div>
                        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, fontWeight: 600, color: COLORS.ink, margin: 0 }}>
                          {r.data?.[campo] || "(sin nombre)"}
                        </p>
                        <p style={{ fontFamily: "Inter, sans-serif", fontSize: 11, color: COLORS.muted, margin: "2px 0 0" }}>
                          Eliminado hace {dias} día{dias !== 1 ? "s" : ""}
                        </p>
                      </div>
                      <div style={{ display: "flex", gap: 8 }}>
                        <button className="drx-btn-ghost" style={{ ...buttonGhost, padding: "5px 10px", fontSize: 12 }} onClick={() => restaurar(tipo, r.id)}>
                          Restaurar
                        </button>
                        <button
                          className="drx-btn-ghost"
                          style={{ ...buttonGhost, padding: "5px 10px", fontSize: 12, color: "#B42318", borderColor: "#F3B4AC" }}
                          onClick={() => borrarDefinitivo(tipo, r.id)}
                        >
                          Borrar para siempre
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
}

